questionvariables.text:
col(v) := matrix([v[1]],[v[2]]);
/* Design: decide which arrows are equal to a; two categories in a fixed order. Entries [a, [[category, column] for p, q, r, s]]: 1 or 2 equal arrows, and the equal arrow's position varies. Source: original. */
L: [[[1,-2],[["swap",[-2,1]],["rev",[-1,2]],["sgn",[-1,-2]],["eq",[1,-2]]]],[[2,1],[["sgn",[2,-1]],["dbl",[4,2]],["rev",[-2,-1]],["eq",[2,1]]]],[[2,-1],[["rev",[-2,1]],["dbl",[4,-2]],["eq",[2,-1]],["swap",[-1,2]]]],[[-3,1],[["rev",[3,-1]],["eq",[-3,1]],["eq",[-3,1]],["swap",[1,-3]]]],[[-2,-1],[["sgn",[-2,1]],["swap",[-1,-2]],["rev",[2,1]],["eq",[-2,-1]]]],[[3,-1],[["swap",[-1,3]],["rev",[-3,1]],["eq",[3,-1]],["dbl",[6,-2]]]],[[-1,2],[["rev",[1,-2]],["eq",[-1,2]],["eq",[-1,2]],["sgn",[1,2]]]],[[-3,2],[["eq",[-3,2]],["rev",[3,-2]],["dbl",[-6,4]],["sgn",[3,2]]]],[[-3,-2],[["rev",[3,2]],["sgn",[3,-2]],["eq",[-3,-2]],["swap",[-2,-3]]]],[[-3,-1],[["rev",[3,1]],["eq",[-3,-1]],["swap",[-1,-3]],["sgn",[3,-1]]]]];
ix: 1+rand(10);
av: L[ix][1];
cells: [[0,5],[7,5],[0,0],[7,0]];
/* category code: 1 eq, 2 rev, 3 swap, 4 dbl, 5 sgn */
cc(s) := if s="eq" then 1 elseif s="rev" then 2 elseif s="swap" then 3 elseif s="dbl" then 4 else 5;
/* tail inside the 7 by 5 cell so the whole arrow fits */
tl(c, v) := [c[1] + (if v[1] >= 0 then 1 else 6), c[2] + (if v[2] >= 0 then 1 else 4)];
cat1: cc(L[ix][2][1][1]); c1: L[ix][2][1][2];
t1: tl(cells[1], c1); h1: t1+c1;
opt1: [["eq1", is(cat1=1), "equal to a"], ["neq1", is(cat1#1), "not equal to a"]];
ta1: first(mcq_correct(opt1));
wr1: if cat1=1 then "neq1" else "eq1";
cat2: cc(L[ix][2][2][1]); c2: L[ix][2][2][2];
t2: tl(cells[2], c2); h2: t2+c2;
opt2: [["eq2", is(cat2=1), "equal to a"], ["neq2", is(cat2#1), "not equal to a"]];
ta2: first(mcq_correct(opt2));
wr2: if cat2=1 then "neq2" else "eq2";
cat3: cc(L[ix][2][3][1]); c3: L[ix][2][3][2];
t3: tl(cells[3], c3); h3: t3+c3;
opt3: [["eq3", is(cat3=1), "equal to a"], ["neq3", is(cat3#1), "not equal to a"]];
ta3: first(mcq_correct(opt3));
wr3: if cat3=1 then "neq3" else "eq3";
cat4: cc(L[ix][2][4][1]); c4: L[ix][2][4][2];
t4: tl(cells[4], c4); h4: t4+c4;
opt4: [["eq4", is(cat4=1), "equal to a"], ["neq4", is(cat4#1), "not equal to a"]];
ta4: first(mcq_correct(opt4));
wr4: if cat4=1 then "neq4" else "eq4";
cs: [cat1, cat2, cat3, cat4];
